	"zportfolio/i18n/i18n.properties":'# This is the resource bundle for zportfolio\n\n#Texts for manifest.json\n\n#XTIT: Application name\nappTitle=Arijit\'s Portfolio\n\n#YDES: Application description\nappDescription=An SAP Fiori application.\n#XTIT: Main view title\ntitle=Arijit&#39;s Portfolio\n\n# ===== Hero Section =====\n#XTIT: Hero name\nheroName=Arijit Dhar\n#XTXT: Hero subtitle\nheroSubtitle=SAP UI5 / Fiori Developer | 3.8+ Years Experience\n#XTXT: Hero profile summary\nheroSummary=SAP Fiori/UI5 Developer with 3.8 years of hands-on experience in designing, developing, and deploying custom SAP Fiori Apps. Skilled in maintaining and enhancing standard Fiori applications to adapt to evolving business needs.\n#XBUT: Download CV button\nbtnDownloadCV=Download CV\n#XBUT: Contact me button\nbtnContactMe=Contact Me\n#XTXT: Hero location pill\nheroLocation=Bengaluru, India\n#XTXT: Hero apps pill\nheroApps=25+ Apps Built\n#XTXT: Hero customers pill\nheroCustomers=50K+ Customers\n\n# ===== Stats Bar =====\n#XTXT: Stat number - years\nstatYears=3.4+\n#XTXT: Stat label - years\nstatYearsLabel=Years Experience\n#XTXT: Stat number - apps\nstatApps=25+\n#XTXT: Stat label - apps\nstatAppsLabel=Custom Apps\n#XTXT: Stat number - customers\nstatCustomers=50K+\n#XTXT: Stat label - customers\nstatCustomersLabel=Customers Served\n#XTXT: Stat number - UX improvement\nstatUX=30%\n#XTXT: Stat label - UX improvement\nstatUXLabel=UX Improvement\n\n# ===== Skills Section =====\n#XTIT: Skills section title\nsectionSkills=Skills & Expertise\n\n# ===== Professional Experience =====\n#XTIT: Experience section title\nsectionExperience=Professional Experience\n#XTXT: Employer name\nexpEmployer=Capgemini Technology Services India Limited\n#XTXT: Role title\nexpRole=Consultant\n#XTXT: Duration\nexpDuration=2022 - Present\n#XTXT: Location\nexpLocation=Bengaluru, Karnataka\n#XTXT: Regions\nexpRegions=EU & APAC Regions\n#XTXT: Years status\nexpYears=3.8+ Years\n#XTXT: Experience summary\nexpSummary=Transforming business requirements via 25+ scalable, end-to-end custom SAP UI5/Fiori applications on both S4HANA On-Premises and Cloud for global clients across EU and APAC regions. Expertise in modernizing legacy business processes through innovative Freestyle SAP Fiori solutions in industries such as Pharma, Power Grids, and Commercial Gases.\n\n# ===== Projects Section =====\n#XTIT: Projects section title\nsectionProjects=Projects\n\n#XTXT: Air Liquide project\nprojAirLiquideTitle=Air Liquide\nprojAirLiquideDate=09/2024 - Present\nprojAirLiquideRole=Consultant - Team Lead\nprojAirLiquideSummary=Led the team to a successful Go-Live of complex SAP UI5 Freestyle and Fiori Elements custom applications. Worked on Adaptation Variants and CFL Extensions of Standard Fiori Apps, and directly coordinated with Business Solution Architects and BPOs for technical design, solutioning, and implementation.\n\n#XTXT: Ausgrid project\nprojAusgridTitle=Ausgrid\nprojAusgridDate=05/2024 - 09/2024\nprojAusgridRole=Consultant\nprojAusgridSummary=Rapid Content activation for 300+ SAP Fiori Apps for S4HANA EWM Implementation, saving 120+ work hours and reducing human error by 80%. Replaced existing Power BI reports with modern SAP UI5 Freestyle Apps and managed Fiori Launchpad Administration on S4HANA On-Premises and SAP Build Workzone on BTP.\n\n#XTXT: Servier Laboratories project\nprojServierTitle=Servier Laboratories\nprojServierDate=10/2022 - 04/2024\nprojServierRole=Consultant\nprojServierSummary=Extended 3 standard Fiori apps and A2X APIs with custom fields and logic. Developed 7 custom freestyle and Fiori Elements apps, maintained SAP Fiori Launchpad, and conducted 10+ training sessions for 300+ end users achieving 95% user adoption rate.\n\n# ===== Education Section =====\n#XTIT: Education section title\nsectionEducation=Education\n#XTXT: B.Tech details\neduBTechTitle=B.Tech - Electronics & Communication Engineering\neduBTechInst=National Institute of Technology, Agartala\neduBTechYear=2018 - 2022\n#XTXT: HSC details\neduHSCTitle=Higher Secondary Certificate (HSC)\neduHSCInst=Bhavans Tripura Vidya Mandir, Agartala\n\n# ===== Contact / Footer =====\n#XTIT: Contact section title\nsectionContact=Get In Touch\n#XTXT: Footer subtitle\nfooterSubtitle=Feel free to reach out for collaborations, opportunities, or just a friendly chat about SAP UI5 development.\n#XTXT: Email label\ncontactEmailLabel=Email\n#XTXT: Email\ncontactEmail=arijit99aj@gmail.com\n#XTXT: Phone label\ncontactPhoneLabel=Phone\n#XTXT: Phone\ncontactPhone=+91 7085271874\n#XTXT: LinkedIn label\ncontactLinkedInLabel=LinkedIn\n#XTXT: LinkedIn\ncontactLinkedIn=LinkedIn Profile\n#XBUT: Download resume button\nbtnDownloadResume=Download Resume\n#XTXT: Footer copyright\nfooterCopyright=\\u00a9 2026 Arijit Dhar. Built with SAP UI5.',
